import heapq

def main():
    N, M = map(int, input().split())
    edge = [[] for _ in range(N)]
    for _ in range(M):
        l, d, k, c, A, B = map(int, input().split())
        A -= 1
        B -= 1
        edge[B].append((l, d, k, c, A))

    for S in range(N - 1):
        P = [(0, S)]
        heapq.heapify(P)
        ans = [-1] * N
        while P:
            time, pos = heapq.heappop(P)
            if ans[pos] != -1:
                continue
            ans[pos] = time
            for l, d, k, c, A in edge[pos]:
                if ans[A] != -1:
                    continue
                kt = (time - c - l) // d
                if kt < 0:
                    continue
                if kt > k - 1:
                    kt = k - 1
                heapq.heappush(P, (-(kt * d + l), A))

        print(ans[N-1] if ans[N-1] != -1 else '-Infinity')

main()
